export const GENERATED_EXERCISES = [
  {"id":"fx-bent-over-barbell-row","name":"Bent Over Barbell Row","muscle":"Back","category":"Upper Body","equipment":"Barbell","notes":"Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position."},
  {"id":"fx-bent-over-one-arm-long-bar-row","name":"Bent Over One-Arm Long Bar Row","muscle":"Back","category":"Upper Body","equipment":"Barbell","notes":"Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward. Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","unilateral":true},
  {"id":"fx-bent-over-two-arm-long-bar-row","name":"Bent Over Two-Arm Long Bar Row","muscle":"Back","category":"Upper Body","equipment":"Barbell","notes":"Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward. Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent."},
  {"id":"fx-bent-over-two-dumbbell-row","name":"Bent Over Two-Dumbbell Row","muscle":"Back","category":"Upper Body","equipment":"Dumbbell","notes":"With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position."},
  {"id":"fx-bent-over-two-dumbbell-row-with-palms-in","name":"Bent Over Two-Dumbbell Row With Palms In","muscle":"Back","category":"Upper Body","equipment":"Dumbbell","notes":"With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position."},
  {"id":"fx-cable-incline-pushdown","name":"Cable Incline Pushdown","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position."},
  {"id":"fx-close-grip-front-lat-pulldown","name":"Close-Grip Front Lat Pulldown","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar."},
  {"id":"fx-dumbbell-incline-row","name":"Dumbbell Incline Row","muscle":"Back","category":"Upper Body","equipment":"Dumbbell","notes":"Using a neutral grip, lean into an incline bench. Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position. Retract the shoulder blades and flex the elbows to row the dumbbells to your side. Pause at the top of the motion, and then return to the starting position."},
  {"id":"fx-elevated-cable-rows","name":"Elevated Cable Rows","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height. Place it on the seat of the cable row machine. Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the V-bar handles."},
  {"id":"fx-full-range-of-motion-lat-pulldown","name":"Full Range-Of-Motion Lat Pulldown","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward."},
  {"id":"fx-incline-bench-pull","name":"Incline Bench Pull","muscle":"Back","category":"Upper Body","equipment":"Barbell","notes":"Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees. Let the arms hang to your sides fully extended as they point to the floor. Turn the wrists until your hands have a pronated (palms down) grip. Now flare the elbows out. This will be your starting position."},
  {"id":"fx-kneeling-high-pulley-row","name":"Kneeling High Pulley Row","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position. Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out. After pausing briefly, slowly return to the starting position."},
  {"id":"fx-kneeling-single-arm-high-pulley-row","name":"Kneeling Single-Arm High Pulley Row","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Attach a single handle to a high pulley and make your weight selection. Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position. Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.","unilateral":true},
  {"id":"fx-leverage-high-row","name":"Leverage High Row","muscle":"Back","category":"Upper Body","equipment":"Machine","notes":"Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position. Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handles to the starting position."},
  {"id":"fx-lying-t-bar-row","name":"Lying T-Bar Row","muscle":"Back","category":"Upper Body","equipment":"Machine","notes":"Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad. Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize."},
  {"id":"fx-one-arm-lat-pulldown","name":"One Arm Lat Pulldown","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position. Pull the handle down, squeezing your elbow to your side as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handle to the starting position. For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.","unilateral":true},
  {"id":"fx-one-arm-dumbbell-row","name":"One-Arm Dumbbell Row","muscle":"Back","category":"Upper Body","equipment":"Dumbbell","notes":"Choose a flat bench and place a dumbbell on each side of it. Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.","unilateral":true},
  {"id":"fx-one-arm-long-bar-row","name":"One-Arm Long Bar Row","muscle":"Back","category":"Upper Body","equipment":"Barbell","notes":"Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end. Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position. Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.","unilateral":true},
  {"id":"fx-reverse-grip-bent-over-rows","name":"Reverse Grip Bent-Over Rows","muscle":"Back","category":"Upper Body","equipment":"Barbell","notes":"Stand erect while holding a barbell with a supinated grip (palms facing up). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position."},
  {"id":"fx-rope-straight-arm-pulldown","name":"Rope Straight-Arm Pulldown","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position. Keeping your arms straight, extend the shoulder to pull the rope down to your thighs. Pause at the bottom of the motion, squeezing your lats."},
  {"id":"fx-seated-one-arm-cable-pulley-rows","name":"Seated One-arm Cable Pulley Rows","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.","unilateral":true},
  {"id":"fx-smith-machine-bent-over-row","name":"Smith Machine Bent Over Row","muscle":"Back","category":"Upper Body","equipment":"Machine","notes":"Set the barbell attached to the smith machine to a height that is about 2 inches below your knees. Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up."},
  {"id":"fx-stiff-leg-barbell-good-morning","name":"Stiff Leg Barbell Good Morning","muscle":"Back","category":"Upper Body","equipment":"Barbell","notes":"This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso."},
  {"id":"fx-straight-bar-bench-mid-rows","name":"Straight Bar Bench Mid Rows","muscle":"Back","category":"Upper Body","equipment":"Barbell","notes":"Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position. Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking. After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down."},
  {"id":"fx-t-bar-row-with-handle","name":"T-Bar Row with Handle","muscle":"Back","category":"Upper Body","equipment":"Barbell","notes":"Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end. Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position. Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position."},
  {"id":"fx-underhand-cable-pulldowns","name":"Underhand Cable Pulldowns","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width."},
  {"id":"fx-v-bar-pulldown","name":"V-Bar Pulldown","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Sit down on a pull-down machine with a V-Bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position."},
  {"id":"fx-v-bar-pullup","name":"V-Bar Pullup","muscle":"Back","category":"Upper Body","equipment":"Bodyweight","notes":"Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles."},
  {"id":"fx-wide-grip-lat-pulldown","name":"Wide-Grip Lat Pulldown","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar."},
  {"id":"fx-wide-grip-pulldown-behind-the-neck","name":"Wide-Grip Pulldown Behind The Neck","muscle":"Back","category":"Upper Body","equipment":"Cable","notes":"Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar."},
  {"id":"fx-wide-grip-rear-pull-up","name":"Wide-Grip Rear Pull-Up","muscle":"Back","category":"Upper Body","equipment":"Bodyweight","notes":"Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position."},
  {"id":"fx-alternate-hammer-curl","name":"Alternate Hammer Curl","muscle":"Biceps","category":"Upper Body","equipment":"Dumbbell","notes":"Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. This will be your starting position.","unilateral":true},
  {"id":"fx-alternate-incline-dumbbell-curl","name":"Alternate Incline Dumbbell Curl","muscle":"Biceps","category":"Upper Body","equipment":"Dumbbell","notes":"Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.","unilateral":true},
  {"id":"fx-barbell-curls-lying-against-an-incline","name":"Barbell Curls Lying Against An Incline","muscle":"Biceps","category":"Upper Body","equipment":"Barbell","notes":"Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position. While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms."},
  {"id":"fx-cable-hammer-curls-rope-attachment","name":"Cable Hammer Curls - Rope Attachment","muscle":"Biceps","category":"Upper Body","equipment":"Cable","notes":"Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it. Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary. Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position."},
  {"id":"fx-cable-preacher-curl","name":"Cable Preacher Curl","muscle":"Biceps","category":"Upper Body","equipment":"Cable","notes":"Place a preacher bench about 2 feet in front of a pulley machine. Attach a straight bar to the low pulley. Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley. Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position."},
  {"id":"fx-close-grip-ez-bar-curl","name":"Close-Grip EZ Bar Curl","muscle":"Biceps","category":"Upper Body","equipment":"Barbell","notes":"Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move."},
  {"id":"fx-close-grip-standing-barbell-curl","name":"Close-Grip Standing Barbell Curl","muscle":"Biceps","category":"Upper Body","equipment":"Barbell","notes":"Hold a barbell with both hands, palms up and a few inches apart. Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement."},
  {"id":"fx-dumbbell-alternate-bicep-curl","name":"Dumbbell Alternate Bicep Curl","muscle":"Biceps","category":"Upper Body","equipment":"Dumbbell","notes":"Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.","unilateral":true},
  {"id":"fx-high-cable-curls","name":"High Cable Curls","muscle":"Biceps","category":"Upper Body","equipment":"Cable","notes":"Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position."},
  {"id":"fx-incline-hammer-curls","name":"Incline Hammer Curls","muscle":"Biceps","category":"Upper Body","equipment":"Dumbbell","notes":"Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position. Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary. Continue to the top of the movement and pause, then slowly return to the start position."},
  {"id":"fx-lying-close-grip-bar-curl-on-high-pulley","name":"Lying Close-Grip Bar Curl On High Pulley","muscle":"Biceps","category":"Upper Body","equipment":"Cable","notes":"Place a flat bench in front of a high pulley or lat pulldown machine. Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width. Lie on your back with your head over the end of the bench. Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position."},
  {"id":"fx-machine-bicep-curl","name":"Machine Bicep Curl","muscle":"Biceps","category":"Upper Body","equipment":"Machine","notes":"Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position. Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm. Pause at the top of the movement, and then slowly return the weight to the starting position."},
  {"id":"fx-machine-preacher-curls","name":"Machine Preacher Curls","muscle":"Biceps","category":"Upper Body","equipment":"Machine","notes":"Sit down on the Preacher Curl Machine and select the weight. Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position."},
  {"id":"fx-one-arm-dumbbell-preacher-curl","name":"One Arm Dumbbell Preacher Curl","muscle":"Biceps","category":"Upper Body","equipment":"Dumbbell","notes":"Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position. As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.","unilateral":true},
  {"id":"fx-preacher-hammer-dumbbell-curl","name":"Preacher Hammer Dumbbell Curl","muscle":"Biceps","category":"Upper Body","equipment":"Dumbbell","notes":"Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip). As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height."},
  {"id":"fx-reverse-cable-curl","name":"Reverse Cable Curl","muscle":"Biceps","category":"Upper Body","equipment":"Cable","notes":"Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position."},
  {"id":"fx-seated-dumbbell-curl","name":"Seated Dumbbell Curl","muscle":"Biceps","category":"Upper Body","equipment":"Dumbbell","notes":"Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso. Rotate the palms of the hands so that they are facing your torso. This will be your starting position."},
  {"id":"fx-seated-dumbbell-inner-biceps-curl","name":"Seated Dumbbell Inner Biceps Curl","muscle":"Biceps","category":"Upper Body","equipment":"Dumbbell","notes":"Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position. While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips:"},
  {"id":"fx-spider-curl","name":"Spider Curl","muscle":"Biceps","category":"Upper Body","equipment":"Barbell","notes":"Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off. Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench."},
  {"id":"fx-standing-biceps-cable-curl","name":"Standing Biceps Cable Curl","muscle":"Biceps","category":"Upper Body","equipment":"Cable","notes":"Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position."},
  {"id":"fx-calf-press","name":"Calf Press","muscle":"Calves","category":"Lower Body","equipment":"Machine","notes":"Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform. Select an appropriate weight, and grasp the handles. This will be your starting position."},
  {"id":"fx-calf-press-on-the-leg-press-machine","name":"Calf Press On The Leg Press Machine","muscle":"Calves","category":"Lower Body","equipment":"Machine","notes":"Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance."},
  {"id":"fx-dumbbell-seated-one-leg-calf-raise","name":"Dumbbell Seated One-Leg Calf Raise","muscle":"Calves","category":"Lower Body","equipment":"Dumbbell","notes":"Place a block on the floor about 12 inches from a flat bench. Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee. Now place the ball of your left foot on the block. This will be your starting position. Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.","unilateral":true},
  {"id":"fx-smith-machine-calf-raise","name":"Smith Machine Calf Raise","muscle":"Calves","category":"Lower Body","equipment":"Machine","notes":"Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders. Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position."},
  {"id":"fx-smith-machine-reverse-calf-raises","name":"Smith Machine Reverse Calf Raises","muscle":"Calves","category":"Lower Body","equipment":"Machine","notes":"Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar. Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance."},
  {"id":"fx-standing-calf-raises","name":"Standing Calf Raises","muscle":"Calves","category":"Lower Body","equipment":"Machine","notes":"Adjust the padded lever of the calf raise machine to fit your height."},
  {"id":"fx-standing-dumbbell-calf-raise","name":"Standing Dumbbell Calf Raise","muscle":"Calves","category":"Lower Body","equipment":"Dumbbell","notes":"Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position."},
  {"id":"fx-alternating-floor-press","name":"Alternating Floor Press","muscle":"Chest","category":"Upper Body","equipment":"Kettlebell","notes":"Lie on the floor with two kettlebells next to your shoulders. Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward. Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell. Raise the kettlebell and repeat on the opposite side.","unilateral":true},
  {"id":"fx-cable-chest-press","name":"Cable Chest Press","muscle":"Chest","category":"Upper Body","equipment":"Cable","notes":"Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement."},
  {"id":"fx-decline-dumbbell-bench-press","name":"Decline Dumbbell Bench Press","muscle":"Chest","category":"Upper Body","equipment":"Dumbbell","notes":"Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position."},
  {"id":"fx-decline-dumbbell-flyes","name":"Decline Dumbbell Flyes","muscle":"Chest","category":"Upper Body","equipment":"Dumbbell","notes":"Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position."},
  {"id":"fx-decline-smith-press","name":"Decline Smith Press","muscle":"Chest","category":"Upper Body","equipment":"Machine","notes":"Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position. As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso."},
  {"id":"fx-dumbbell-bench-press-with-neutral-grip","name":"Dumbbell Bench Press with Neutral Grip","muscle":"Chest","category":"Upper Body","equipment":"Dumbbell","notes":"Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted. Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position. Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso."},
  {"id":"fx-hammer-grip-incline-db-bench-press","name":"Hammer Grip Incline DB Bench Press","muscle":"Chest","category":"Upper Body","equipment":"Dumbbell","notes":"Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width."},
  {"id":"fx-incline-cable-chest-press","name":"Incline Cable Chest Press","muscle":"Chest","category":"Upper Body","equipment":"Cable","notes":"Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement."},
  {"id":"fx-incline-dumbbell-bench-with-palms-facing-in","name":"Incline Dumbbell Bench With Palms Facing In","muscle":"Chest","category":"Upper Body","equipment":"Dumbbell","notes":"Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width."},
  {"id":"fx-incline-dumbbell-flyes","name":"Incline Dumbbell Flyes","muscle":"Chest","category":"Upper Body","equipment":"Dumbbell","notes":"Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees. Extend your arms above you with a slight bend at the elbows. Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position."},
  {"id":"fx-incline-push-up","name":"Incline Push-Up","muscle":"Chest","category":"Upper Body","equipment":"Bodyweight","notes":"Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width. Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms. Push body up until arms are extended. Repeat."},
  {"id":"fx-incline-push-up-reverse-grip","name":"Incline Push-Up Reverse Grip","muscle":"Chest","category":"Upper Body","equipment":"Bodyweight","notes":"Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands on the bar palms up, with your hands about shoulder width apart. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms."},
  {"id":"fx-leverage-chest-press","name":"Leverage Chest Press","muscle":"Chest","category":"Upper Body","equipment":"Machine","notes":"Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow."},
  {"id":"fx-leverage-decline-chest-press","name":"Leverage Decline Chest Press","muscle":"Chest","category":"Upper Body","equipment":"Machine","notes":"Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow."},
  {"id":"fx-leverage-incline-chest-press","name":"Leverage Incline Chest Press","muscle":"Chest","category":"Upper Body","equipment":"Machine","notes":"Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow."},
  {"id":"fx-machine-bench-press","name":"Machine Bench Press","muscle":"Chest","category":"Upper Body","equipment":"Machine","notes":"Sit down on the Chest Press Machine and select the weight. Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms."},
  {"id":"fx-one-arm-dumbbell-bench-press","name":"One Arm Dumbbell Bench Press","muscle":"Chest","category":"Upper Body","equipment":"Dumbbell","notes":"Lie down on a flat bench with a dumbbell in one hand on top of your thigh. By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly. Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.","unilateral":true},
  {"id":"fx-push-up-wide","name":"Push-Up Wide","muscle":"Chest","category":"Upper Body","equipment":"Bodyweight","notes":"With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position. To begin, allow the elbows to flex, lowering your chest to the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step."},
  {"id":"fx-push-ups-with-feet-elevated","name":"Push-Ups With Feet Elevated","muscle":"Chest","category":"Upper Body","equipment":"Bodyweight","notes":"Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length. Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is. Lower yourself until your chest almost touches the floor as you inhale."},
  {"id":"fx-single-arm-push-up","name":"Single-Arm Push-Up","muscle":"Chest","category":"Upper Body","equipment":"Bodyweight","notes":"Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up. Maintain good posture, and place your free hand behind your back. This will be your starting position.","unilateral":true},
  {"id":"fx-smith-machine-bench-press","name":"Smith Machine Bench Press","muscle":"Chest","category":"Upper Body","equipment":"Machine","notes":"Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position."},
  {"id":"fx-smith-machine-decline-press","name":"Smith Machine Decline Press","muscle":"Chest","category":"Upper Body","equipment":"Machine","notes":"Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench. Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position. Begin the movement by flexing your arms, lowering the bar to your chest."},
  {"id":"fx-standing-cable-chest-press","name":"Standing Cable Chest Press","muscle":"Chest","category":"Upper Body","equipment":"Cable","notes":"Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability. Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position. Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you."},
  {"id":"fx-straight-arm-dumbbell-pullover","name":"Straight-Arm Dumbbell Pullover","muscle":"Chest","category":"Upper Body","equipment":"Dumbbell","notes":"Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well."},
  {"id":"fx-wide-grip-barbell-bench-press","name":"Wide-Grip Barbell Bench Press","muscle":"Chest","category":"Upper Body","equipment":"Barbell","notes":"Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest."},
  {"id":"fx-wide-grip-decline-barbell-bench-press","name":"Wide-Grip Decline Barbell Bench Press","muscle":"Chest","category":"Upper Body","equipment":"Barbell","notes":"Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your lower chest."},
  {"id":"fx-ab-crunch-machine","name":"Ab Crunch Machine","muscle":"Core","category":"Core","equipment":"Machine","notes":"Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position."},
  {"id":"fx-air-bike","name":"Air Bike","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position. Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position."},
  {"id":"fx-alternate-heel-touchers","name":"Alternate Heel Touchers","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position. Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement. Now go back slowly to the starting position as you inhale.","unilateral":true},
  {"id":"fx-barbell-side-bend","name":"Barbell Side Bend","muscle":"Core","category":"Core","equipment":"Barbell","notes":"Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position. While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary."},
  {"id":"fx-bent-knee-hip-raise","name":"Bent-Knee Hip Raise","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lay flat on the floor with your arms next to your sides. Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches."},
  {"id":"fx-cable-reverse-crunch","name":"Cable Reverse Crunch","muscle":"Core","category":"Core","equipment":"Cable","notes":"Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it. Sit down with your feet toward the pulley and attach the cable to your ankles. Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are. With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor."},
  {"id":"fx-cable-seated-crunch","name":"Cable Seated Crunch","muscle":"Core","category":"Core","equipment":"Cable","notes":"Seat on a flat bench with your back facing a high pulley. Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position. With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step."},
  {"id":"fx-cross-body-crunch","name":"Cross-Body Crunch","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lie flat on your back and bend your knees about 60 degrees. Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position."},
  {"id":"fx-decline-crunch","name":"Decline Crunch","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Secure your legs at the end of the decline bench and lie down. Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head. While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it."},
  {"id":"fx-decline-oblique-crunch","name":"Decline Oblique Crunch","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Secure your legs at the end of the decline bench and slowly lay down on the bench. Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor. Put one hand beside your head and the other on your thigh. This will be your starting position."},
  {"id":"fx-decline-reverse-crunch","name":"Decline Reverse Crunch","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don't let your body slip down from this position. Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position."},
  {"id":"fx-dumbbell-side-bend","name":"Dumbbell Side Bend","muscle":"Core","category":"Core","equipment":"Dumbbell","notes":"Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position."},
  {"id":"fx-flat-bench-leg-pull-in","name":"Flat Bench Leg Pull-In","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lie on an exercise mat or a flat bench with your legs off the end. Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position."},
  {"id":"fx-flat-bench-lying-leg-raise","name":"Flat Bench Lying Leg Raise","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lie with your back flat on a bench and your legs extended in front of you off the end. Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position."},
  {"id":"fx-leg-pull-in","name":"Leg Pull-In","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position."},
  {"id":"fx-oblique-crunches","name":"Oblique Crunches","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor. Make sure your feet are elevated and resting on a flat surface. Now lift the shoulder in which your hand is touching your head."},
  {"id":"fx-one-arm-high-pulley-cable-side-bends","name":"One-Arm High-Pulley Cable Side Bends","muscle":"Core","category":"Core","equipment":"Cable","notes":"Connect a standard handle to a tower. Move cable to highest pulley position. Stand with side to cable. With one hand, reach up and grab handle with underhand grip. Pull down cable until elbow touches your side and the handle is by your shoulder. Position feet hip-width apart. Place free hand on hip to help gauge pivot point.","unilateral":true},
  {"id":"fx-pallof-press-with-rotation","name":"Pallof Press With Rotation","muscle":"Core","category":"Core","equipment":"Cable","notes":"Connect a standard handle to a tower, and position the cable to shoulder height. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable."},
  {"id":"fx-reverse-crunch","name":"Reverse Crunch","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise. Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position."},
  {"id":"fx-rope-crunch","name":"Rope Crunch","muscle":"Core","category":"Core","equipment":"Cable","notes":"Kneel 1-2 feet in front of a cable system with a rope attached. After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position. To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down. Pause at the bottom of the motion, and then slowly return to the starting position."},
  {"id":"fx-seated-barbell-twist","name":"Seated Barbell Twist","muscle":"Core","category":"Core","equipment":"Barbell","notes":"Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other. Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended."},
  {"id":"fx-seated-flat-bench-leg-pull-in","name":"Seated Flat Bench Leg Pull-In","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position. Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement. After a second pause, go back to the starting position as you inhale."},
  {"id":"fx-smith-machine-hip-raise","name":"Smith Machine Hip Raise","muscle":"Core","category":"Core","equipment":"Machine","notes":"Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position."},
  {"id":"fx-standing-cable-wood-chop","name":"Standing Cable Wood Chop","muscle":"Core","category":"Core","equipment":"Cable","notes":"Connect a standard handle to a tower, and move the cable to the highest pulley position. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable."},
  {"id":"fx-standing-rope-crunch","name":"Standing Rope Crunch","muscle":"Core","category":"Core","equipment":"Cable","notes":"Attach a rope to a high pulley and select an appropriate weight. Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position. Perform the movement by flexing the spine, crunching the weight down as far as you can. Hold the peak contraction for a moment before returning to the starting position."},
  {"id":"fx-tuck-crunch","name":"Tuck Crunch","muscle":"Core","category":"Core","equipment":"Bodyweight","notes":"To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down. Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs."},
  {"id":"fx-cable-wrist-curl","name":"Cable Wrist Curl","muscle":"Forearms","category":"Upper Body","equipment":"Cable","notes":"Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment. Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees. Start out by curling your wrist upwards and exhaling. Keep the contraction for a second."},
  {"id":"fx-dumbbell-lying-pronation","name":"Dumbbell Lying Pronation","muscle":"Forearms","category":"Upper Body","equipment":"Dumbbell","notes":"Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it. Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm."},
  {"id":"fx-palms-down-dumbbell-wrist-curl-over-a-bench","name":"Palms-Down Dumbbell Wrist Curl Over A Bench","muscle":"Forearms","category":"Upper Body","equipment":"Dumbbell","notes":"Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling."},
  {"id":"fx-palms-down-wrist-curl-over-a-bench","name":"Palms-Down Wrist Curl Over A Bench","muscle":"Forearms","category":"Upper Body","equipment":"Barbell","notes":"Start out by placing a barbell on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling."},
  {"id":"fx-palms-up-barbell-wrist-curl-over-a-bench","name":"Palms-Up Barbell Wrist Curl Over A Bench","muscle":"Forearms","category":"Upper Body","equipment":"Barbell","notes":"Start out by placing a barbell on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling."},
  {"id":"fx-palms-up-dumbbell-wrist-curl-over-a-bench","name":"Palms-Up Dumbbell Wrist Curl Over A Bench","muscle":"Forearms","category":"Upper Body","equipment":"Dumbbell","notes":"Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling."},
  {"id":"fx-seated-dumbbell-palms-down-wrist-curl","name":"Seated Dumbbell Palms-Down Wrist Curl","muscle":"Forearms","category":"Upper Body","equipment":"Dumbbell","notes":"Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs."},
  {"id":"fx-seated-dumbbell-palms-up-wrist-curl","name":"Seated Dumbbell Palms-Up Wrist Curl","muscle":"Forearms","category":"Upper Body","equipment":"Dumbbell","notes":"Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs."},
  {"id":"fx-seated-one-arm-dumbbell-palms-up-wrist-curl","name":"Seated One-Arm Dumbbell Palms-Up Wrist Curl","muscle":"Forearms","category":"Upper Body","equipment":"Dumbbell","notes":"Sit on a flat bench with a dumbbell in your right hand. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position.","unilateral":true},
  {"id":"fx-seated-palm-up-barbell-wrist-curl","name":"Seated Palm-Up Barbell Wrist Curl","muscle":"Forearms","category":"Upper Body","equipment":"Barbell","notes":"Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as possible while inhaling and keeping a tight grip."},
  {"id":"fx-seated-palms-down-barbell-wrist-curl","name":"Seated Palms-Down Barbell Wrist Curl","muscle":"Forearms","category":"Upper Body","equipment":"Barbell","notes":"Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as possible while inhaling and keeping a tight grip."},
  {"id":"fx-seated-two-arm-palms-up-low-pulley-wrist-curl","name":"Seated Two-Arm Palms-Up Low-Pulley Wrist Curl","muscle":"Forearms","category":"Upper Body","equipment":"Cable","notes":"Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it. Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up. Now hold the handle with both hands, palms up, using a shoulder-width grip. Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor."},
  {"id":"fx-glute-kickback","name":"Glute Kickback","muscle":"Glutes","category":"Lower Body","equipment":"Bodyweight","notes":"Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","unilateral":true},
  {"id":"fx-one-legged-cable-kickback","name":"One-Legged Cable Kickback","muscle":"Glutes","category":"Lower Body","equipment":"Cable","notes":"Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle. Face the weight stack from a distance of about two feet, grasping the steel frame for support.","unilateral":true},
  {"id":"fx-single-leg-glute-bridge","name":"Single Leg Glute Bridge","muscle":"Glutes","category":"Lower Body","equipment":"Bodyweight","notes":"Lay on the floor with your feet flat and knees bent. Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position. Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground. Extend as far as possible, pause and then return to the starting position.","unilateral":true},
  {"id":"fx-step-up-with-knee-raise","name":"Step-up with Knee Raise","muscle":"Glutes","category":"Lower Body","equipment":"Bodyweight","notes":"Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position. Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.","unilateral":true},
  {"id":"fx-alternating-hang-clean","name":"Alternating Hang Clean","muscle":"Legs","category":"Lower Body","equipment":"Kettlebell","notes":"Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead. Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.","unilateral":true},
  {"id":"fx-band-hip-adductions","name":"Band Hip Adductions","muscle":"Legs","category":"Lower Body","equipment":"Bands","notes":"Anchor a band around a solid post or other object. Stand with your left side to the post, and put your right foot through the band, getting it around the ankle. Stand up straight and hold onto the post if needed. This will be your starting position. Keeping the knee straight, raise your right legs out to the side as far as you can."},
  {"id":"fx-barbell-full-squat","name":"Barbell Full Squat","muscle":"Legs","category":"Lower Body","equipment":"Barbell","notes":"This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso."},
  {"id":"fx-barbell-lunge","name":"Barbell Lunge","muscle":"Legs","category":"Lower Body","equipment":"Barbell","notes":"This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","unilateral":true},
  {"id":"fx-barbell-side-split-squat","name":"Barbell Side Split Squat","muscle":"Legs","category":"Lower Body","equipment":"Barbell","notes":"Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position. Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.","unilateral":true},
  {"id":"fx-barbell-step-ups","name":"Barbell Step Ups","muscle":"Legs","category":"Lower Body","equipment":"Barbell","notes":"Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.","unilateral":true},
  {"id":"fx-barbell-walking-lunge","name":"Barbell Walking Lunge","muscle":"Legs","category":"Lower Body","equipment":"Barbell","notes":"Begin standing with your feet shoulder width apart and a barbell across your upper back. Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot. Drive through the heel of your lead foot and extend both knees to raise yourself back up.","unilateral":true},
  {"id":"fx-bodyweight-squat","name":"Bodyweight Squat","muscle":"Legs","category":"Lower Body","equipment":"Bodyweight","notes":"Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position. Begin the movement by flexing your knees and hips, sitting back with your hips. Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."},
  {"id":"fx-cable-deadlifts","name":"Cable Deadlifts","muscle":"Legs","category":"Lower Body","equipment":"Cable","notes":"Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights. To begin, squat down be flexing your hips and knees until you can reach the handles. After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement."},
  {"id":"fx-cable-hip-adduction","name":"Cable Hip Adduction","muscle":"Legs","category":"Lower Body","equipment":"Cable","notes":"Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away. Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley. Now step out and away from the stack with a wide stance and grasp the bar of the pulley system."},
  {"id":"fx-dumbbell-lunges","name":"Dumbbell Lunges","muscle":"Legs","category":"Lower Body","equipment":"Dumbbell","notes":"Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","unilateral":true},
  {"id":"fx-dumbbell-squat","name":"Dumbbell Squat","muscle":"Legs","category":"Lower Body","equipment":"Dumbbell","notes":"Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs)."},
  {"id":"fx-dumbbell-squat-to-a-bench","name":"Dumbbell Squat To A Bench","muscle":"Legs","category":"Lower Body","equipment":"Dumbbell","notes":"Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs)."},
  {"id":"fx-dumbbell-step-ups","name":"Dumbbell Step Ups","muscle":"Legs","category":"Lower Body","equipment":"Dumbbell","notes":"Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs). Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","unilateral":true},
  {"id":"fx-elevated-back-lunge","name":"Elevated Back Lunge","muscle":"Legs","category":"Lower Body","equipment":"Barbell","notes":"Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you. Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position. Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.","unilateral":true},
  {"id":"fx-glute-ham-raise","name":"Glute Ham Raise","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad. Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright."},
  {"id":"fx-lunge-pass-through","name":"Lunge Pass Through","muscle":"Legs","category":"Lower Body","equipment":"Kettlebell","notes":"Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position. Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground. As you lunge, pass the kettlebell under your front leg to your opposite hand. Pressing through the heel of your foot, return to the starting position.","unilateral":true},
  {"id":"fx-lying-leg-curls","name":"Lying Leg Curls","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment."},
  {"id":"fx-lying-machine-squat","name":"Lying Machine Squat","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel."},
  {"id":"fx-narrow-stance-hack-squats","name":"Narrow Stance Hack Squats","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided. Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times."},
  {"id":"fx-narrow-stance-leg-press","name":"Narrow Stance Leg Press","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times."},
  {"id":"fx-narrow-stance-squats","name":"Narrow Stance Squats","muscle":"Legs","category":"Lower Body","equipment":"Barbell","notes":"This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso."},
  {"id":"fx-reverse-hyperextension","name":"Reverse Hyperextension","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position. To begin the movement, flex the hips, pulling the legs forward. Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion."},
  {"id":"fx-seated-leg-curl","name":"Seated Leg Curl","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad."},
  {"id":"fx-single-leg-leg-extension","name":"Single-Leg Leg Extension","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities. Maintaining good posture, fully extend one leg, pausing at the top of the motion. Return to the starting position without letting the weight stop, keeping tension on the muscle.","unilateral":true},
  {"id":"fx-smith-machine-leg-press","name":"Smith Machine Leg Press","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position. Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees."},
  {"id":"fx-smith-machine-pistol-squat","name":"Smith Machine Pistol Squat","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders. Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3","unilateral":true},
  {"id":"fx-smith-machine-squat","name":"Smith Machine Squat","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso."},
  {"id":"fx-smith-machine-stiff-legged-deadlift","name":"Smith Machine Stiff-Legged Deadlift","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight."},
  {"id":"fx-smith-single-leg-split-squat","name":"Smith Single-Leg Split Squat","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","unilateral":true},
  {"id":"fx-standing-leg-curl","name":"Standing Leg Curl","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad."},
  {"id":"fx-stiff-legged-barbell-deadlift","name":"Stiff-Legged Barbell Deadlift","muscle":"Legs","category":"Lower Body","equipment":"Barbell","notes":"Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position."},
  {"id":"fx-stiff-legged-dumbbell-deadlift","name":"Stiff-Legged Dumbbell Deadlift","muscle":"Legs","category":"Lower Body","equipment":"Dumbbell","notes":"Grasp a couple of dumbbells holding them by your side at arm's length. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position."},
  {"id":"fx-thigh-adductor","name":"Thigh Adductor","muscle":"Legs","category":"Lower Body","equipment":"Machine","notes":"To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position. Slowly press against the machine with your legs to move them towards each other while exhaling."},
  {"id":"fx-wide-stance-barbell-squat","name":"Wide Stance Barbell Squat","muscle":"Legs","category":"Lower Body","equipment":"Barbell","notes":"This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso."},
  {"id":"fx-alternating-cable-shoulder-press","name":"Alternating Cable Shoulder Press","muscle":"Shoulders","category":"Upper Body","equipment":"Cable","notes":"Move the cables to the bottom of the tower and select an appropriate weight. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press one side directly over head. After pausing at the top, return to the starting position and repeat on the opposite side.","unilateral":true},
  {"id":"fx-alternating-deltoid-raise","name":"Alternating Deltoid Raise","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"In a standing position, hold a pair of dumbbells at your side. Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating. Return the weights to your side. On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.","unilateral":true},
  {"id":"fx-arnold-dumbbell-press","name":"Arnold Dumbbell Press","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl. Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward."},
  {"id":"fx-barbell-rear-delt-row","name":"Barbell Rear Delt Row","muscle":"Shoulders","category":"Upper Body","equipment":"Barbell","notes":"Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip. Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter \"T\". Now you are ready to begin the exercise."},
  {"id":"fx-barbell-shoulder-press","name":"Barbell Shoulder Press","muscle":"Shoulders","category":"Upper Body","equipment":"Barbell","notes":"Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward). Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position. Lower the bar down to the shoulders slowly as you inhale."},
  {"id":"fx-bent-over-low-pulley-side-lateral","name":"Bent Over Low-Pulley Side Lateral","muscle":"Shoulders","category":"Upper Body","equipment":"Cable","notes":"Select a weight and hold the handle of the low pulley with your right hand. Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position."},
  {"id":"fx-cable-rope-rear-delt-rows","name":"Cable Rope Rear-Delt Rows","muscle":"Shoulders","category":"Upper Body","equipment":"Cable","notes":"Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back. Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out. Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position."},
  {"id":"fx-cable-seated-lateral-raise","name":"Cable Seated Lateral Raise","muscle":"Shoulders","category":"Upper Body","equipment":"Cable","notes":"Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley. Now sit at the edge of the flat bench behind you with your feet placed in front of your knees. Bend forward while keeping your back flat and rest your torso on the thighs."},
  {"id":"fx-cable-shoulder-press","name":"Cable Shoulder Press","muscle":"Shoulders","category":"Upper Body","equipment":"Cable","notes":"Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press the handles directly over head. After pausing at the top, return to the starting position and repeat."},
  {"id":"fx-dumbbell-one-arm-shoulder-press","name":"Dumbbell One-Arm Shoulder Press","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight. Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.","unilateral":true},
  {"id":"fx-dumbbell-one-arm-upright-row","name":"Dumbbell One-Arm Upright Row","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs. Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.","unilateral":true},
  {"id":"fx-dumbbell-scaption","name":"Dumbbell Scaption","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up. Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement. Continue until your arms are parallel to the ground, and then return to the starting position."},
  {"id":"fx-front-cable-raise","name":"Front Cable Raise","muscle":"Shoulders","category":"Upper Body","equipment":"Cable","notes":"Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand. Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms' length with the palms of the hand facing your thighs. This will be your starting position."},
  {"id":"fx-leverage-shoulder-press","name":"Leverage Shoulder Press","muscle":"Shoulders","category":"Upper Body","equipment":"Machine","notes":"Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position. Press the handles upward by extending through the elbow."},
  {"id":"fx-low-pulley-row-to-neck","name":"Low Pulley Row To Neck","muscle":"Shoulders","category":"Upper Body","equipment":"Cable","notes":"Sit on a low pulley row machine with a rope attachment. Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position."},
  {"id":"fx-one-arm-incline-lateral-raise","name":"One-Arm Incline Lateral Raise","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel. Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.","unilateral":true},
  {"id":"fx-one-arm-side-laterals","name":"One-Arm Side Laterals","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance. Stand with a straight torso and have the dumbbell by your side at arm's length with the palm of the hand facing you. This will be your starting position.","unilateral":true},
  {"id":"fx-power-partials","name":"Power Partials","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position. Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling."},
  {"id":"fx-seated-barbell-military-press","name":"Seated Barbell Military Press","muscle":"Shoulders","category":"Upper Body","equipment":"Barbell","notes":"Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down."},
  {"id":"fx-seated-cable-shoulder-press","name":"Seated Cable Shoulder Press","muscle":"Shoulders","category":"Upper Body","equipment":"Cable","notes":"Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together above your head. After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables."},
  {"id":"fx-seated-dumbbell-press","name":"Seated Dumbbell Press","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs. Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side. Rotate the wrists so that the palms of your hands are facing forward. This is your starting position. As you exhale, push the dumbbells up until they touch at the top."},
  {"id":"fx-see-saw-press-alternating-side-press","name":"See-Saw Press (Alternating Side Press)","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Grab a dumbbell with each hand and stand up erect. Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.","unilateral":true},
  {"id":"fx-smith-machine-one-arm-upright-row","name":"Smith Machine One-Arm Upright Row","muscle":"Shoulders","category":"Upper Body","equipment":"Machine","notes":"With the bar at thigh level, load an appropriate weight. Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position. Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor.","unilateral":true},
  {"id":"fx-smith-machine-overhead-shoulder-press","name":"Smith Machine Overhead Shoulder Press","muscle":"Shoulders","category":"Upper Body","equipment":"Machine","notes":"To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell."},
  {"id":"fx-standing-alternating-dumbbell-press","name":"Standing Alternating Dumbbell Press","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position. Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement. After a brief pause, return the weight to the starting position. Repeat for the opposite side, continuing to alternate between arms.","unilateral":true},
  {"id":"fx-standing-dumbbell-press","name":"Standing Dumbbell Press","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position. Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head. Pause, and slowly return the weight to the starting position."},
  {"id":"fx-standing-military-press","name":"Standing Military Press","muscle":"Shoulders","category":"Upper Body","equipment":"Barbell","notes":"Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other. Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other."},
  {"id":"fx-standing-palm-in-one-arm-dumbbell-press","name":"Standing Palm-In One-Arm Dumbbell Press","muscle":"Shoulders","category":"Upper Body","equipment":"Dumbbell","notes":"Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.","unilateral":true},
  {"id":"fx-barbell-shrug-behind-the-back","name":"Barbell Shrug Behind The Back","muscle":"Traps","category":"Upper Body","equipment":"Barbell","notes":"Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position."},
  {"id":"fx-cable-shrugs","name":"Cable Shrugs","muscle":"Traps","category":"Upper Body","equipment":"Cable","notes":"Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip. Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position."},
  {"id":"fx-dumbbell-shrug","name":"Dumbbell Shrug","muscle":"Traps","category":"Upper Body","equipment":"Dumbbell","notes":"Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides. Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down. Lower the dumbbells back to the original position."},
  {"id":"fx-leverage-shrug","name":"Leverage Shrug","muscle":"Traps","category":"Upper Body","equipment":"Machine","notes":"Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up."},
  {"id":"fx-smith-machine-behind-the-back-shrug","name":"Smith Machine Behind the Back Shrug","muscle":"Traps","category":"Upper Body","equipment":"Machine","notes":"With the bar at thigh level, load an appropriate weight. Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position. Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement."},
  {"id":"fx-smith-machine-upright-row","name":"Smith Machine Upright Row","muscle":"Traps","category":"Upper Body","equipment":"Machine","notes":"To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight. Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position."},
  {"id":"fx-standing-dumbbell-upright-row","name":"Standing Dumbbell Upright Row","muscle":"Traps","category":"Upper Body","equipment":"Dumbbell","notes":"Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position."},
  {"id":"fx-upright-cable-row","name":"Upright Cable Row","muscle":"Traps","category":"Upper Body","equipment":"Cable","notes":"Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position."},
  {"id":"fx-bench-dips","name":"Bench Dips","muscle":"Triceps","category":"Upper Body","equipment":"Bodyweight","notes":"For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position."},
  {"id":"fx-cable-incline-triceps-extension","name":"Cable Incline Triceps Extension","muscle":"Triceps","category":"Upper Body","equipment":"Cable","notes":"Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor."},
  {"id":"fx-cable-lying-triceps-extension","name":"Cable Lying Triceps Extension","muscle":"Triceps","category":"Upper Body","equipment":"Cable","notes":"Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down. With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position."},
  {"id":"fx-cable-one-arm-tricep-extension","name":"Cable One Arm Tricep Extension","muscle":"Triceps","category":"Upper Body","equipment":"Cable","notes":"With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.","unilateral":true},
  {"id":"fx-cable-rope-overhead-triceps-extension","name":"Cable Rope Overhead Triceps Extension","muscle":"Triceps","category":"Upper Body","equipment":"Cable","notes":"Attach a rope to the bottom pulley of the pulley machine. Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position."},
  {"id":"fx-close-grip-barbell-bench-press","name":"Close-Grip Barbell Bench Press","muscle":"Triceps","category":"Upper Body","equipment":"Barbell","notes":"Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement."},
  {"id":"fx-close-grip-dumbbell-press","name":"Close-Grip Dumbbell Press","muscle":"Triceps","category":"Upper Body","equipment":"Dumbbell","notes":"Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor."},
  {"id":"fx-close-grip-ez-bar-press","name":"Close-Grip EZ-Bar Press","muscle":"Triceps","category":"Upper Body","equipment":"Barbell","notes":"Lie on a flat bench with an EZ bar loaded to an appropriate weight. Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position. Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement."},
  {"id":"fx-close-grip-push-up-off-of-a-dumbbell","name":"Close-Grip Push-Up off of a Dumbbell","muscle":"Triceps","category":"Upper Body","equipment":"Bodyweight","notes":"Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position. Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag. Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step."},
  {"id":"fx-decline-close-grip-bench-to-skull-crusher","name":"Decline Close-Grip Bench To Skull Crusher","muscle":"Triceps","category":"Upper Body","equipment":"Barbell","notes":"Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack."},
  {"id":"fx-decline-dumbbell-triceps-extension","name":"Decline Dumbbell Triceps Extension","muscle":"Triceps","category":"Upper Body","equipment":"Dumbbell","notes":"Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position."},
  {"id":"fx-decline-ez-bar-triceps-extension","name":"Decline EZ Bar Triceps Extension","muscle":"Triceps","category":"Upper Body","equipment":"Barbell","notes":"Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack."},
  {"id":"fx-dip-machine","name":"Dip Machine","muscle":"Triceps","category":"Upper Body","equipment":"Machine","notes":"Sit securely in a dip machine, select the weight and firmly grasp the handles. Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle. As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle."},
  {"id":"fx-dumbbell-floor-press","name":"Dumbbell Floor Press","muscle":"Triceps","category":"Upper Body","equipment":"Dumbbell","notes":"Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you. Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side. Pause at the bottom, and then bring the weight together at the top by extending through the elbows."},
  {"id":"fx-dumbbell-tricep-extension-pronated-grip","name":"Dumbbell Tricep Extension -Pronated Grip","muscle":"Triceps","category":"Upper Body","equipment":"Dumbbell","notes":"Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor. The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position. Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in."},
  {"id":"fx-floor-press","name":"Floor Press","muscle":"Triceps","category":"Upper Body","equipment":"Barbell","notes":"Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks."},
  {"id":"fx-incline-push-up-close-grip","name":"Incline Push-Up Close-Grip","muscle":"Triceps","category":"Upper Body","equipment":"Bodyweight","notes":"Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands next to one another on the bar. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms."},
  {"id":"fx-one-arm-floor-press","name":"One Arm Floor Press","muscle":"Triceps","category":"Upper Body","equipment":"Barbell","notes":"Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent. Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso). Make sure the hand you are not using to lift the weight is placed by your side.","unilateral":true},
  {"id":"fx-reverse-triceps-bench-press","name":"Reverse Triceps Bench Press","muscle":"Triceps","category":"Upper Body","equipment":"Barbell","notes":"Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position."},
  {"id":"fx-smith-machine-close-grip-bench-press","name":"Smith Machine Close-Grip Bench Press","muscle":"Triceps","category":"Upper Body","equipment":"Machine","notes":"Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position."},
];
